mapper.select:
select * from marketing_product_spu_rental_method_property where is_deleted = 0 and marketing_spu_id in
#{id}
order by marketing_spu_id asc, rental_method asc, rental_period_month asc, id asc

mapper.update:
update marketing_product_spu_rental_method_property
set is_deleted = 1,
    update_by = #{updateBy},
    update_time = #{updateTime}
where marketing_spu_id = #{marketingSpuId}
  and is_deleted = 0
